import {
  ServiceDescriptor,
  ServiceIdentifier,
  isCollectionId,
  isConstructorId,
  isConstructorServiceDescriptor,
} from '../types';
import { disposeValue } from '../types/disposable';
import { ServiceResolutionFunc, ServiceResolutionMiddleware, ServiceResolver } from './types';

/**
 * Resolves services using a middleware pipeline.
 */
export class MiddlewareServiceResolver implements ServiceResolver {
  #serviceDescriptors: ReadonlySet<ServiceDescriptor>;

  #middlewares: ServiceResolutionMiddleware[];

  #pipeline: ServiceResolutionFunc;

  constructor(
    serviceDescriptors: ReadonlySet<ServiceDescriptor>,
    middlewares: ServiceResolutionMiddleware[],
  ) {
    this.#serviceDescriptors = serviceDescriptors;
    this.#middlewares = middlewares;
    this.#pipeline = middlewares.reduceRight<ServiceResolutionFunc>(
      (processNext, currentMiddleware) => (context) =>
        currentMiddleware.handle(context, () => processNext(context)),
      () => null,
    );
  }

  /**
   * Resolves all services matching the given identifier.
   * @param identifier - The service identifier to resolve
   * @param scopeId - The current scope identifier
   * @returns Array of resolved service instances
   */
  resolveServices<T>(identifier: ServiceIdentifier<T>, scopeId: symbol): T[] {
    return this.#getServiceDescriptorsViaIdentifier(identifier)
      .map((descriptor) => ({
        serviceIdentifier: identifier,
        serviceDescriptor: descriptor,
        scopeId,
        serviceResolver: this,
      }))
      .map(this.#pipeline)
      .filter(Boolean) as T[];
  }

  #getServiceDescriptorsViaIdentifier<T>(identifier: ServiceIdentifier<T>): ServiceDescriptor[] {
    return [...this.#serviceDescriptors].filter((descriptor) => {
      if (isConstructorId(identifier) && isConstructorServiceDescriptor(descriptor)) {
        return descriptor.implementation === identifier;
      }

      if (isCollectionId(identifier)) {
        return descriptor.aliases?.some((alias) => identifier.baseId === alias);
      }

      return descriptor.aliases?.some((alias) => identifier === alias);
    });
  }

  async disposeScope(scopeId: symbol): Promise<void> {
    const results = await Promise.allSettled(
      this.#middlewares.map(async (middleware) => {
        if ('disposeScope' in middleware && typeof middleware.disposeScope === 'function') {
          await middleware.disposeScope(scopeId);
        }
      }),
    );

    const failures = results.filter((r): r is PromiseRejectedResult => r.status === 'rejected');

    if (failures.length > 0) {
      throw new AggregateError(
        failures.map((f) => f.reason),
        `${failures.length} middleware(s) failed to dispose scope`,
      );
    }
  }

  async dispose(): Promise<void> {
    const results = await Promise.allSettled(
      this.#middlewares.map((middleware) => disposeValue(middleware)),
    );

    const failures = results.filter((r): r is PromiseRejectedResult => r.status === 'rejected');

    if (failures.length > 0) {
      throw new AggregateError(
        failures.map((f) => f.reason),
        `${failures.length} middleware(s) failed to dispose`,
      );
    }
  }
}
