import { Constructor, InterfaceId } from '../types';

const interfaceImplementations = new WeakMap<Constructor, Set<InterfaceId<unknown>>>();

/**
 * Decorator that marks a class as implementing a specific interface.
 * @param interfaceId - The identifier for the interface being implemented
 * @returns A class decorator function
 */
export const Implements =
  <I extends object>(interfaceId: InterfaceId<I>) =>
  <T extends I>(target: Constructor<T>, context: DecoratorContext): void => {
    if (context) {
      if (context.kind !== 'class') {
        throw new Error('Implements decorator can only be used on classes.');
      }
    }

    let interfaces = interfaceImplementations.get(target);
    if (!interfaces) {
      interfaces = new Set<InterfaceId<unknown>>();
      interfaceImplementations.set(target, interfaces);
    }

    interfaces.add(interfaceId);
  };

/**
 * Retrieves all interfaces implemented by a class and its ancestors.
 * @param ctor - The constructor of the class to check
 * @returns An array of interface identifiers
 */
export function getImplementedInterfaces<T>(
  ctor: Constructor<T>,
): ReadonlyArray<InterfaceId<unknown>> {
  const result = new Set<InterfaceId<unknown>>();

  let current: Constructor = ctor;
  while (current && current !== Object.prototype) {
    const interfaces = interfaceImplementations.get(current);
    if (interfaces && interfaces.size > 0) {
      for (const id of interfaces) {
        result.add(id);
      }
    }
    current = Object.getPrototypeOf(current);
  }

  return Array.from(result);
}
