/**
 * Interface for objects that can be disposed.
 */
export interface Disposable {
  dispose(): void;
}

/**
 * Interface for objects that require asynchronous disposal.
 * Consumers implement this with the disposeAsync() method or via native [Symbol.asyncDispose].
 */
export interface AsyncDisposable {
  disposeAsync(): Promise<void>;
}

/**
 * Union type representing any object that can be asynchronously disposed,
 * either via the AsyncDisposable interface or the native Symbol.asyncDispose protocol.
 */
export type AsyncDisposableObject = AsyncDisposable | { [Symbol.asyncDispose](): Promise<void> };

/**
 * Checks if a value implements the Disposable interface.
 * @param value - Value to check
 * @returns True if the value is disposable
 */
export function isDisposable(value: unknown): value is Disposable {
  if (value === null || value === undefined || typeof value !== 'object') return false;

  if ('dispose' in value && typeof value.dispose === 'function') {
    return true;
  }

  return false;
}

/**
 * Checks if a value implements the AsyncDisposable interface (disposeAsync method)
 * or the native [Symbol.asyncDispose] protocol.
 * @param value - Value to check
 * @returns True if the value is async disposable via either pattern
 */
export function isAsyncDisposable(value: unknown): value is AsyncDisposableObject {
  if (value === null || value === undefined || typeof value !== 'object') return false;

  if ('disposeAsync' in value && typeof value.disposeAsync === 'function') {
    return true;
  }

  if (Symbol.asyncDispose in value && typeof value[Symbol.asyncDispose] === 'function') {
    return true;
  }

  return false;
}

/**
 * Disposes a value asynchronously, supporting both interface patterns.
 * Checks in order: Symbol.asyncDispose, disposeAsync(), dispose().
 * @param value - Value to dispose
 */
export async function disposeValue(value: unknown): Promise<void> {
  if (value === null || value === undefined || typeof value !== 'object') return;

  const obj = value as Record<string | symbol, unknown>;

  if (Symbol.asyncDispose in obj && typeof obj[Symbol.asyncDispose] === 'function') {
    await (obj[Symbol.asyncDispose] as () => Promise<void>)();
    return;
  }

  if ('disposeAsync' in obj && typeof obj.disposeAsync === 'function') {
    await (obj.disposeAsync as () => Promise<void>)();
    return;
  }

  if (isDisposable(value)) {
    value.dispose();
  }
}
