import { join } from 'node:path';
import { Logger } from '@gitlab-org/logging';
import { RepositoryDiscoveryService, StatelessRepository } from '@gitlab-org/repositories';
import { FallbackFileAccessService } from '../fallback_file_access_service';

/**
 * Validates that a file exists in a git repository and is not gitignored.
 *
 * @param filePath - Relative path to the file within the workspace folder
 * @param workspaceFolderPath - Absolute path to the workspace folder
 * @param repositoryService - a RepositoryService instance
 * @param logger - a Logger instance
 * @throws Error when the file is gitignored or not in a git repository
 */
export async function assertValidRepoFile(
  filePath: string,
  workspaceFolderPath: string,
  fileAccessService: FallbackFileAccessService,
  repositoryService: RepositoryDiscoveryService,
  logger: Logger,
): Promise<StatelessRepository> {
  const fullFilePath = join(workspaceFolderPath, filePath);

  const fullRealFilePath = await fileAccessService.realPath(fullFilePath);

  if (fullRealFilePath === '') {
    const errorMessage = `Path did not refer to a valid file or symlink: "${filePath}" could not be resolved`;
    logger.error(errorMessage);
    throw new Error(errorMessage);
  } else {
    logger.debug(`Path "${filePath}" resolved to "${fullRealFilePath}"`);
  }

  // Resolve the workspace folder path through realPath as well, so that both
  // paths use the same base when the workspace is accessed through a symlink.
  // Without this, getMatchingRepository fails because it compares the resolved
  // file path (e.g. /gitlab-gdk/...) against the unresolved workspace path
  // (e.g. /home/gdk/... -> /gitlab-gdk/...).
  const realWorkspaceFolderPath = await fileAccessService.realPath(workspaceFolderPath);
  if (realWorkspaceFolderPath === '') {
    const errorMessage = `Workspace folder path could not be resolved: "${workspaceFolderPath}"`;
    logger.error(errorMessage);
    throw new Error(errorMessage);
  }

  const repo = await repositoryService.getMatchingRepository(
    fullRealFilePath,
    realWorkspaceFolderPath,
  );
  if (!repo) {
    if (fullFilePath !== fullRealFilePath) {
      const errorMessage = `File/Directory is not in repository: "${filePath}" points to "${fullRealFilePath}"`;
      logger.error(errorMessage);
      throw new Error(errorMessage);
    }
    const errorMessage = `File/Directory is not in repository: "${filePath}"`;
    logger.error(errorMessage);
    throw new Error(errorMessage);
  }

  if ((await repo.checkIgnore([fullRealFilePath])).length > 0) {
    const errorMessage = `File/Directory is .gitignored: "${fullRealFilePath}"`;
    logger.error(errorMessage);
    throw new Error(errorMessage);
  }

  return repo;
}
