/**
 * Represents a constructor function with optional arguments.
 */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export type Constructor<T = any, Args extends any[] = any[]> = new (...params: Args) => T;

/**
 * Runtime identifier for an interface type.
 * @template T - The service type
 */
export interface InterfaceId<T> {
  readonly symbol: symbol;
  readonly __type: T;
}

/**
 * Runtime identifier for a collection of services.
 * @template T - The service type
 */
export interface CollectionId<T> {
  readonly __type: T[];
  readonly baseId: InterfaceId<T>;
}

/**
 * Returns the element type for array types, otherwise the type itself.
 */
type ElementType<T> = T extends (infer U)[] ? U : T;

/**
 * Union of all possible identifiers for a service.
 */
export type ServiceIdentifier<T = unknown> =
  | Constructor<T>
  | InterfaceId<T>
  | (T extends unknown[] ? CollectionId<ElementType<T>> : CollectionId<T>);

/**
 * Checks if an identifier is a constructor.
 */
export function isConstructorId(id: ServiceIdentifier): id is Constructor<unknown> {
  return typeof id === 'function';
}

/**
 * Checks if an identifier is an interface ID.
 */
export function isInterfaceId(id: ServiceIdentifier): id is InterfaceId<unknown> {
  return 'symbol' in id;
}

/**
 * Checks if an identifier is a collection ID.
 */
export function isCollectionId(id: ServiceIdentifier): id is CollectionId<unknown> {
  return 'baseId' in id;
}
