import { ServiceDescriptor } from '../types';
import { MiddlewareServiceResolver } from './middleware_service_resolver';
import {
  SingletonResolutionMiddleware,
  ConstructorResolutionMiddleware,
  InstanceResolutionMiddleware,
  ScopedResolutionMiddleware,
} from './middleware';
import { FactoryResolutionMiddleware } from './middleware/factory_resolution_middleware';

/**
 * Creates a resolver with the standard middleware pipeline.
 * @param serviceDescriptors - Set of registered service descriptors
 * @returns A configured service resolver
 */
export const createDefaultServiceResolver = (
  serviceDescriptors: ReadonlySet<ServiceDescriptor>,
) => {
  return new MiddlewareServiceResolver(serviceDescriptors, [
    new InstanceResolutionMiddleware(),
    new SingletonResolutionMiddleware(),
    new ScopedResolutionMiddleware(),
    new FactoryResolutionMiddleware(),
    new ConstructorResolutionMiddleware(),
  ]);
};
