import { ServiceDescriptor } from '../types';
import { CompositeValidator } from './composite_validator';
import { ServiceValidator, ValidationResult } from './types';
import { createValidationContext } from './utils';
import {
  CircularDependencyValidator,
  DependencyExistenceValidator,
  SingleImplementationValidator,
} from './validators';

function createDefaultValidator(): ServiceValidator {
  return new CompositeValidator([
    new DependencyExistenceValidator(),
    new SingleImplementationValidator(),
    new CircularDependencyValidator(),
  ]);
}

export function validateServiceDescriptors(
  descriptors: ReadonlySet<ServiceDescriptor>,
): ValidationResult {
  const validator = createDefaultValidator();
  const validationContext = createValidationContext(descriptors);
  return validator.validate(validationContext);
}
