import { ServiceIdentifier } from '../../types';
import { getServiceName } from '../../errors/utils';

/**
 * Error thrown when circular dependencies are detected in the service graph.
 */
export class CircularDependencyError extends Error {
  constructor(cycle: ServiceIdentifier[]) {
    const cycleNames = cycle.map((id) => getServiceName(id)).join(' -> ');
    super(`Circular dependency detected: ${cycleNames}`);
    this.name = 'CircularDependencyError';
  }
}
