import { isFactoryServiceDescriptor } from '../../types';
import { ServiceResolutionContext, ServiceResolutionMiddleware } from '../types';
import { ContextualServiceLocator } from '../../contextual_service_locator';

export class FactoryResolutionMiddleware implements ServiceResolutionMiddleware {
  handle<T>(context: ServiceResolutionContext<T>, next: () => T | null): T | null {
    if (!isFactoryServiceDescriptor(context.serviceDescriptor)) {
      return next();
    }

    const contextualLocator = new ContextualServiceLocator(
      context.serviceResolver,
      context.scopeId,
    );

    return context.serviceDescriptor.factory(contextualLocator);
  }
}
