import { promises as fs } from 'node:fs';
import { join, sep } from 'node:path';
import { Injectable } from '@gitlab/needle';
import { RepositoryDiscoveryService } from '@gitlab-org/repositories';
import { Logger, withPrefix } from '@gitlab-org/logging';
import { PlainTextResponse } from '@gitlab-org/duo-workflow-service';
import { ToolInputDisplay } from '@gitlab-lsp/workflow-api';
import { WorkflowAction } from '../clients/types';
import { WorkflowActionContext, WorkflowActionHandler, WorkflowActionOf } from './index';

export type ListDirectoryAction = WorkflowActionOf<'listDirectory'>;

@Injectable(WorkflowActionHandler, [Logger, RepositoryDiscoveryService])
export class ListDirectoryActionHandler implements WorkflowActionHandler<ListDirectoryAction> {
  #logger: Logger;

  #repositoryDiscoveryService: RepositoryDiscoveryService;

  constructor(logger: Logger, repositoryDiscoveryService: RepositoryDiscoveryService) {
    this.#logger = withPrefix(logger, '[ListDirectoryActionHandler]');
    this.#repositoryDiscoveryService = repositoryDiscoveryService;
  }

  name = 'list_dir';

  formatInput(args: Record<string, unknown>): ToolInputDisplay {
    return {
      tool: 'list_dir',
      directory: args.directory as string,
    };
  }

  canHandle(action: WorkflowAction): action is ListDirectoryAction {
    return Boolean(action.listDirectory);
  }

  async execute(
    { listDirectory }: ListDirectoryAction,
    { workspaceFolderPath }: WorkflowActionContext,
  ): Promise<PlainTextResponse> {
    const fullDirPath = join(workspaceFolderPath, listDirectory.directory);

    this.#logger.debug(`Listing contents in directory "${fullDirPath}"`);

    const repo = await this.#repositoryDiscoveryService.getMatchingRepository(
      fullDirPath,
      workspaceFolderPath,
    );

    if (!repo) {
      const error = `Directory is not in repository: "${fullDirPath}"`;
      this.#logger.error(error);
      return { error, response: '' };
    }

    try {
      if ((await repo.checkIgnore([fullDirPath])).length > 0) {
        const error = `Directory is .gitignored: "${fullDirPath}"`;
        this.#logger.error(error);
        return { error, response: '' };
      }

      const dirEntries = await fs.readdir(fullDirPath, { withFileTypes: true });
      const absPaths = dirEntries.map((de) => join(de.parentPath, de.name));
      const ignored = await repo.checkIgnore(absPaths);

      const result = dirEntries
        .filter((de) => !ignored.includes(join(de.parentPath, de.name)))
        .map((de) => `${de.name}${de.isDirectory() ? sep : ''}`);

      const response = result.join('\n');
      return { response, error: '' };
    } catch (error) {
      const errorMsg = `Failed to read directory "${fullDirPath}": ${error}`;
      this.#logger.error(errorMsg, error);
      return { error: errorMsg, response: '' };
    }
  }
}
