import { isInstanceServiceDescriptor } from '../../types';
import { ServiceResolutionContext, ServiceResolutionMiddleware } from '../types';

export class InstanceResolutionMiddleware implements ServiceResolutionMiddleware {
  handle<T>(context: ServiceResolutionContext<T>, next: () => T | null): T | null {
    if (!isInstanceServiceDescriptor(context.serviceDescriptor)) {
      return next();
    }

    return context.serviceDescriptor.instance;
  }
}
