import { ServiceIdentifier } from '../types';
import { getServiceName } from './utils';

/**
 * Error thrown when a requested service is not registered.
 */
export class ServiceNotRegisteredError extends Error {
  constructor(serviceId: ServiceIdentifier) {
    super(`No service registered for '${getServiceName(serviceId)}'`);
    this.name = 'ServiceNotRegisteredError';
  }
}
