import {
  CollectionId,
  Constructor,
  InterfaceId,
  ServiceIdentifier,
  ServiceLifetime,
} from '../types';

// Helper types for better inference with collections
export type ResolveIdentifier<T> =
  T extends Constructor<infer U>
    ? U
    : T extends InterfaceId<infer U>
      ? U
      : T extends CollectionId<infer U>
        ? U[]
        : never;

export type ResolveDependencies<T extends readonly ServiceIdentifier[]> = T extends readonly [
  ...infer Rest extends ServiceIdentifier[],
]
  ? { [K in keyof Rest]: ResolveIdentifier<Rest[K]> }
  : never;

export type ServiceMetadata<
  D extends readonly ServiceIdentifier[] = readonly ServiceIdentifier[],
  Lifetime extends ServiceLifetime = ServiceLifetime,
> = {
  dependencies: D;
  lifetime: Lifetime;
  autoActivate?: Lifetime extends ServiceLifetime.Transient ? false : boolean;
};

const serviceMetadata = new WeakMap<Constructor, ServiceMetadata>();

export function Service<
  const D extends readonly ServiceIdentifier[],
  Lifetime extends ServiceLifetime = ServiceLifetime,
>(metadata: ServiceMetadata<D, Lifetime>) {
  return <TClass extends Constructor<unknown, ResolveDependencies<D>>>(
    target: TClass,
    context: DecoratorContext,
  ) => {
    if (context) {
      if (context.kind !== 'class') {
        throw new Error('Service decorator can only be used on classes.');
      }
    }

    serviceMetadata.set(target, metadata);
  };
}

export function isServiceDecorated(target: Constructor): boolean {
  return serviceMetadata.has(target);
}

export function getServiceMetadata(serviceClass: Constructor): ServiceMetadata {
  const metadata = serviceMetadata.get(serviceClass);
  if (!metadata) {
    throw new Error(`Class ${serviceClass.name} is not decorated with @Service`);
  }

  return metadata;
}
