import { Constructor, ServiceIdentifier } from './service_identifier';
import { ServiceLocator } from './service_locator';

const SERVICE_DESCRIPTOR_BRAND = Symbol('SERVICE_DESCRIPTOR_BRAND');

/**
 * Defines the lifetime scope of a service.
 */
export enum ServiceLifetime {
  /** Single instance shared across all requests */
  Singleton = 'singleton',
  /** New instance created for each request */
  Transient = 'transient',
  /** Single instance shared within a scope */
  Scoped = 'scoped',
}

interface BaseServiceDescriptor {
  [SERVICE_DESCRIPTOR_BRAND]: true;
}

// ============================================================================
// Type validation helpers - used across all descriptors
// ============================================================================

/**
 * Validates that type T implements the interface referenced by Alias.
 * Returns the Alias if valid, never if invalid.
 */
type ValidateAlias<T, Alias> =
  Alias extends ServiceIdentifier<infer U> ? (T extends U ? Alias : never) : never;

/**
 * Applies ValidateAlias to each element in an array of aliases.
 * Invalid aliases become 'never', causing a type error.
 */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
type ValidateAliases<T, Aliases extends readonly any[]> = {
  [K in keyof Aliases]: ValidateAlias<T, Aliases[K]>;
};

// ============================================================================
// Service Descriptor Interfaces
// ============================================================================

/**
 * Descriptor for a service registered with a constructor.
 */
export interface ConstructorServiceDescriptor<T, Args extends unknown[] = unknown[]>
  extends BaseServiceDescriptor {
  type: 'Constructor';
  implementation: Constructor<T, Args>;
  aliases?: readonly ServiceIdentifier[];
  dependencies: readonly ServiceIdentifier[];
  lifetime: ServiceLifetime;
  autoActivate: boolean;
}

/**
 * Descriptor for a service registered as an instance.
 */
export interface InstanceServiceDescriptor<T> extends BaseServiceDescriptor {
  type: 'Instance';
  instance: T;
  aliases: readonly ServiceIdentifier[];
}

/**
 * Factory function that creates a service instance.
 */
export type ServiceFactory<T> = (locator: ServiceLocator) => T;

/**
 * Descriptor for a service registered with a factory function.
 */
export interface FactoryServiceDescriptor<T> extends BaseServiceDescriptor {
  type: 'Factory';
  factory: ServiceFactory<T>;
  aliases: readonly ServiceIdentifier[];
  lifetime: ServiceLifetime;
  autoActivate: boolean;
}

/**
 * Union of all possible service descriptors.
 */
export type ServiceDescriptor<T = unknown> =
  | ConstructorServiceDescriptor<T, unknown[]>
  | InstanceServiceDescriptor<T>
  | FactoryServiceDescriptor<T>;

// ============================================================================
// Factory Functions with Type Validation
// ============================================================================

/**
 * Creates a new constructor service descriptor.
 */
export function createConstructorDescriptor<
  T,
  Args extends unknown[] = unknown[],
  const Aliases extends readonly ServiceIdentifier[] = readonly [],
>(options: {
  implementation: Constructor<T, Args>;
  aliases?: ValidateAliases<T, Aliases>;
  dependencies: readonly ServiceIdentifier[];
  lifetime: ServiceLifetime;
  autoActivate: boolean;
}): ConstructorServiceDescriptor<T, Args> {
  return {
    type: 'Constructor',
    ...options,
    aliases: options.aliases as readonly ServiceIdentifier[] | undefined,
    [SERVICE_DESCRIPTOR_BRAND]: true,
  };
}

/**
 * Creates a new instance service descriptor.
 */
export function createInstanceDescriptor<
  T,
  const Aliases extends readonly ServiceIdentifier[] = readonly [],
>(options: { instance: T; aliases: ValidateAliases<T, Aliases> }): InstanceServiceDescriptor<T> {
  return {
    type: 'Instance',
    ...options,
    aliases: options.aliases as readonly ServiceIdentifier[],
    [SERVICE_DESCRIPTOR_BRAND]: true,
  };
}

/**
 * Creates a new factory service descriptor.
 */
export function createFactoryDescriptor<
  // eslint-disable-next-line @typescript-eslint/no-explicit-any -- required for type validation
  Factory extends (locator: ServiceLocator) => any,
  const Aliases extends readonly ServiceIdentifier[] = readonly [],
>(options: {
  factory: Factory;
  aliases: ValidateAliases<ReturnType<Factory>, Aliases>;
  lifetime: ServiceLifetime;
  autoActivate?: boolean;
}): FactoryServiceDescriptor<ReturnType<Factory>> {
  return {
    type: 'Factory',
    autoActivate: options.autoActivate ?? false,
    ...options,
    factory: options.factory as ServiceFactory<ReturnType<Factory>>,
    aliases: options.aliases as readonly ServiceIdentifier[],
    [SERVICE_DESCRIPTOR_BRAND]: true,
  };
}

// ============================================================================
// Utility Functions
// ============================================================================

/**
 * Checks if a descriptor has a specified lifetime.
 */
export function hasLifetime(descriptor: ServiceDescriptor, lifetime: ServiceLifetime) {
  if ('lifetime' in descriptor) {
    return descriptor.lifetime === lifetime;
  }
  return false;
}

/**
 * Checks if a value is a service descriptor.
 */
export function isServiceDescriptor(value: unknown): value is ServiceDescriptor {
  return (
    value !== null &&
    typeof value === 'object' &&
    SERVICE_DESCRIPTOR_BRAND in value &&
    value[SERVICE_DESCRIPTOR_BRAND] === true
  );
}

/**
 * Checks if a descriptor is a constructor service descriptor.
 */
export function isConstructorServiceDescriptor(
  descriptor: ServiceDescriptor,
): descriptor is ConstructorServiceDescriptor<unknown, unknown[]> {
  return descriptor.type === 'Constructor';
}

/**
 * Checks if a descriptor is an instance service descriptor.
 */
export function isInstanceServiceDescriptor<T>(
  descriptor: ServiceDescriptor,
): descriptor is InstanceServiceDescriptor<T> {
  return descriptor.type === 'Instance';
}

/**
 * Checks if a descriptor is a factory service descriptor.
 */
export function isFactoryServiceDescriptor<T>(
  descriptor: ServiceDescriptor,
): descriptor is FactoryServiceDescriptor<T> {
  return descriptor.type === 'Factory';
}
