import {
  isConstructorServiceDescriptor,
  ServiceDescriptor,
  ServiceIdentifier,
  ServiceLifetime,
} from '../types';
import { DescriptorNode, IdentifierLookupMap, ValidationContext, ValidationData } from './types';

export function toDescriptorNode(descriptor: ServiceDescriptor): DescriptorNode {
  const identifiers = [
    ...(descriptor.aliases ?? []),
    ...(isConstructorServiceDescriptor(descriptor) ? [descriptor.implementation] : []),
  ];

  return {
    identifiers,
    dependencyIds: isConstructorServiceDescriptor(descriptor) ? descriptor.dependencies : [],
    lifetime: 'lifetime' in descriptor ? descriptor.lifetime : ServiceLifetime.Transient,
    originalDescriptor: descriptor,
  };
}

export function prepareValidationData(descriptors: ReadonlySet<ServiceDescriptor>): ValidationData {
  const nodes = [...descriptors].map(toDescriptorNode);

  const lookup = nodes.reduce<IdentifierLookupMap>((map, node) => {
    node.identifiers.forEach((identifier) => {
      const arr = map.get(identifier) ?? [];
      arr.push(node);
      map.set(identifier, arr);
    });
    return map;
  }, new Map<ServiceIdentifier, DescriptorNode[]>());

  return {
    nodes,
    lookup,
  };
}

export function createValidationContext(
  descriptors: ReadonlySet<ServiceDescriptor>,
): ValidationContext {
  return {
    descriptors,
    validationData: prepareValidationData(descriptors),
  };
}
