import { isCollectionId, isConstructorId, isInterfaceId, ServiceIdentifier } from '../../types';

export function getServiceName(identifier: ServiceIdentifier): string {
  if (isConstructorId(identifier)) {
    return identifier.name;
  }

  if (isInterfaceId(identifier) && identifier.symbol.description) {
    return identifier.symbol.description;
  }

  if (isCollectionId(identifier)) {
    return `${getServiceName(identifier.baseId)}[]`;
  }

  return 'unkown';
}
