import { ServiceValidator, ValidationContext, ValidationResult } from './types';

export class CompositeValidator implements ServiceValidator {
  readonly name = 'CompositeValidator';

  constructor(private readonly validators: ServiceValidator[]) {}

  validate(context: ValidationContext): ValidationResult {
    const allErrors = this.validators.flatMap((validator) => {
      const result = validator.validate(context);
      return result.isValid ? [] : result.errors;
    });

    return {
      isValid: allErrors.length === 0,
      errors: allErrors,
    };
  }
}
