import { hasLifetime, ServiceDescriptor, ServiceLifetime, AsyncDisposable } from '../../types';
import { disposeValue } from '../../types/disposable';
import { ServiceResolutionContext, ServiceResolutionMiddleware } from '../types';

export class ScopedResolutionMiddleware implements ServiceResolutionMiddleware, AsyncDisposable {
  #scopedInstances = new Map<symbol, Map<ServiceDescriptor, unknown>>();

  handle<T>(context: ServiceResolutionContext, next: () => T | null) {
    if (!hasLifetime(context.serviceDescriptor, ServiceLifetime.Scoped)) {
      return next();
    }

    let scopeMap = this.#scopedInstances.get(context.scopeId);

    if (!scopeMap) {
      scopeMap = new Map<ServiceDescriptor, unknown>();
      this.#scopedInstances.set(context.scopeId, scopeMap);
    }

    if (scopeMap.has(context.serviceDescriptor)) {
      return scopeMap.get(context.serviceDescriptor) as T;
    }

    const service = next();
    if (service) scopeMap.set(context.serviceDescriptor, service);
    return service;
  }

  async disposeScope(scopeId: symbol): Promise<void> {
    const scopeMap = this.#scopedInstances.get(scopeId);
    if (!scopeMap) return;

    const results = await Promise.allSettled(
      [...scopeMap.values()].map((instance) => disposeValue(instance)),
    );

    this.#scopedInstances.delete(scopeId);

    const failures = results.filter((r): r is PromiseRejectedResult => r.status === 'rejected');

    if (failures.length > 0) {
      throw new AggregateError(
        failures.map((f) => f.reason),
        `${failures.length} service(s) failed to dispose`,
      );
    }
  }

  async disposeAsync(): Promise<void> {
    const results = await Promise.allSettled(
      [...this.#scopedInstances.keys()].map((scopeId) => this.disposeScope(scopeId)),
    );

    this.#scopedInstances.clear();

    const failures = results.filter((r): r is PromiseRejectedResult => r.status === 'rejected');

    if (failures.length > 0) {
      throw new AggregateError(
        failures.map((f) => f.reason),
        `${failures.length} scope(s) failed to dispose`,
      );
    }
  }
}
