import { ServiceIdentifier } from '../types';
import { getServiceName } from './utils';

/**
 * Error thrown when a service depends on another service with multiple implementations.
 */
export class MultipleDependencyImplementationsError extends Error {
  constructor(serviceId: ServiceIdentifier, dependencyId: ServiceIdentifier) {
    super(
      `Service '${getServiceName(serviceId)}' depends on '${getServiceName(dependencyId)}' which has multiple implementations registered.`,
    );
    this.name = 'MultipleDependencyImplementationsError';
  }
}
