import { createDefaultServiceResolver } from './resolver';
import { ServiceProvider } from './service_provider';
import { ServiceDescriptor, Constructor, isConstructorServiceDescriptor } from './types';
import { buildConstructorDescriptor } from './utils';
import { validateServiceDescriptors } from './validation';
import { ValidationResult } from './validation/types';

export class ServiceCollection {
  #serviceDescriptors = new Set<ServiceDescriptor>();

  /**
   * Gets the number of registered service descriptors.
   */
  get size(): number {
    return this.#serviceDescriptors.size;
  }

  /**
   * Adds pre-configured service descriptors to the collection.
   *
   * @param descriptors - Service descriptors to add
   * @returns This service collection instance for method chaining
   */
  add(...descriptors: ServiceDescriptor[]) {
    descriptors.forEach((descriptor) => this.#serviceDescriptors.add(descriptor));
    return this;
  }

  /**
   * Adds classes decorated with `@Service` or `@Injectable` to the collection.
   * Automatically creates service descriptors using the class's decorator metadata.
   *
   * @param ctors - Constructor classes to add
   * @returns This service collection instance for method chaining
   * @throws Error if any constructor is not properly decorated
   */
  addClass(...ctors: Constructor[]) {
    const descriptors = ctors.map(buildConstructorDescriptor);
    this.add(...descriptors);
    return this;
  }

  /**
   * Validates the service collection without building a provider.
   * Useful for testing or early validation during application startup.
   *
   * @returns Validation result indicating success or containing errors
   */
  validate(): ValidationResult {
    return validateServiceDescriptors(this.#serviceDescriptors);
  }

  /**
   * Creates a new ServiceProvider with all registered services.
   * Validates service dependencies before building the provider.
   *
   * @returns A configured ServiceProvider
   * @throws AggregateError if validation fails
   */
  build(): ServiceProvider {
    const validationResult = this.validate();
    if (!validationResult.isValid) {
      const errorMessages = validationResult.errors.map((error) => error.message).join('; ');
      throw new AggregateError(
        validationResult.errors,
        `Service validation failed with ${validationResult.errors.length} errors: ${errorMessages}`,
      );
    }

    const resolver = createDefaultServiceResolver(this.#serviceDescriptors);

    const provider = new ServiceProvider(resolver, () => resolver.dispose());

    for (const descriptor of this.#serviceDescriptors) {
      if (isConstructorServiceDescriptor(descriptor) && descriptor.autoActivate) {
        provider.getRequiredService(descriptor.implementation);
      }
    }

    return provider;
  }
}
