import { getImplementedInterfaces, getServiceMetadata } from '../decorators';
import { Constructor, ConstructorServiceDescriptor, createConstructorDescriptor } from '../types';

export function buildConstructorDescriptor<T, Args extends unknown[] = unknown[]>(
  constructor: Constructor<T, Args>,
): ConstructorServiceDescriptor<T, Args> {
  const metadata = getServiceMetadata(constructor);
  const implemented = getImplementedInterfaces(constructor);

  return createConstructorDescriptor({
    implementation: constructor,
    dependencies: metadata.dependencies,
    lifetime: metadata.lifetime,
    aliases: implemented,
    autoActivate: metadata.autoActivate ?? false,
  });
}
