import { AmbiguousMatchError, ServiceNotRegisteredError } from './errors';
import { ServiceIdentifier, ServiceLocator } from './types';
import { ServiceResolver } from './resolver/types';

/**
 * Lightweight ServiceLocator implementation that delegates to a ServiceResolver
 * using a specific scope ID.
 */
export class ContextualServiceLocator implements ServiceLocator {
  constructor(
    private readonly serviceResolver: ServiceResolver,
    private readonly scopeId: symbol,
  ) {}

  getServices<T>(identifier: ServiceIdentifier<T>): T[] {
    return this.serviceResolver.resolveServices(identifier, this.scopeId);
  }

  getRequiredService<T>(identifier: ServiceIdentifier<T>): T {
    const services = this.getServices(identifier);

    if (!services || services.length === 0) {
      throw new ServiceNotRegisteredError(identifier);
    }

    if (services.length > 1) {
      throw new AmbiguousMatchError(identifier);
    }

    return services[0];
  }
}
