import { CircularDependencyError } from '../errors';
import { ServiceIdentifier, isCollectionId } from '../../types';
import { ServiceValidator, ValidationContext, ValidationResult, DescriptorNode } from '../types';

/**
 * Validates that there are no circular dependencies in the service graph.
 *
 * A circular dependency occurs when a service depends on itself, either directly
 * or indirectly through a chain of other services. For example, if Service A depends
 * on Service B, which depends on Service C, which depends back on Service A, this
 * forms a circular dependency that cannot be resolved.
 *
 * This validator uses a depth-first search algorithm to detect cycles in the
 * dependency graph. When a cycle is detected, it provides a clear path showing
 * the chain of dependencies that form the cycle.
 */
export class CircularDependencyValidator implements ServiceValidator {
  readonly name = 'CircularDependencyValidator';

  validate({ validationData }: ValidationContext): ValidationResult {
    const { nodes } = validationData;
    const errors: Error[] = [];

    // Build id-to-node mapping for fast lookups
    const idToNodeMap = new Map<ServiceIdentifier, DescriptorNode>();
    nodes.forEach((node) => {
      node.identifiers.forEach((id) => {
        idToNodeMap.set(id, node);
      });
    });

    // Sets for cycle detection
    const inStack = new Set<ServiceIdentifier>();
    const visited = new Set<ServiceIdentifier>();

    // Check all entry points for cycles
    nodes
      .flatMap((node) => node.identifiers)
      .filter((id) => !visited.has(id))
      .forEach((id) => {
        const cycle = this.#findCircularDependency(id, inStack, visited, idToNodeMap);
        if (cycle.length > 0) {
          errors.push(new CircularDependencyError(cycle));
        }
      });

    return {
      isValid: errors.length === 0,
      errors,
    };
  }

  #findCircularDependency(
    id: ServiceIdentifier,
    inStack: Set<ServiceIdentifier>,
    visited: Set<ServiceIdentifier>,
    idToNodeMap: Map<ServiceIdentifier, DescriptorNode>,
  ): ServiceIdentifier[] {
    // Base cases
    if (inStack.has(id)) return [id]; // Found cycle
    if (visited.has(id)) return []; // Already visited, no cycles here

    // Mark as in-progress and visited
    inStack.add(id);
    visited.add(id);

    const node = idToNodeMap.get(id);
    if (!node) {
      inStack.delete(id);
      return [];
    }

    // Check all dependencies for cycles
    for (const depId of node.dependencyIds) {
      const targetId = isCollectionId(depId) ? depId.baseId : depId;
      const cycle = this.#findCircularDependency(targetId, inStack, visited, idToNodeMap);

      if (cycle.length > 0) {
        inStack.delete(id);
        return [id, ...cycle];
      }
    }

    // No cycles found through this node
    inStack.delete(id);
    return [];
  }
}
