import { MultipleDependencyImplementationsError, UnresolvedDependencyError } from '../../errors';
import { isCollectionId, isConstructorServiceDescriptor } from '../../types';
import { ServiceResolutionContext, ServiceResolutionMiddleware } from '../types';

export class ConstructorResolutionMiddleware implements ServiceResolutionMiddleware {
  handle<T>(context: ServiceResolutionContext<T>, next: () => T | null): T | null {
    if (!isConstructorServiceDescriptor(context.serviceDescriptor)) {
      return next();
    }

    const constructorDependencies = context.serviceDescriptor.dependencies.map((dependency) => {
      if (isCollectionId(dependency)) {
        return context.serviceResolver.resolveServices(dependency.baseId, context.scopeId);
      }

      const services = context.serviceResolver.resolveServices(dependency, context.scopeId);

      if (!services || services.length === 0) {
        throw new UnresolvedDependencyError(context.serviceIdentifier, dependency);
      }

      if (services.length > 1) {
        throw new MultipleDependencyImplementationsError(context.serviceIdentifier, dependency);
      }

      return services[0];
    });

    // eslint-disable-next-line new-cap
    return new context.serviceDescriptor.implementation(...constructorDependencies);
  }
}
