import { ServiceIdentifier } from '../types';
import { getServiceName } from './utils';

/**
 * Error thrown when multiple services are matched, but the default strategy is unable to resolve a single service.
 */
export class AmbiguousMatchError extends Error {
  constructor(serviceId: ServiceIdentifier) {
    super(
      `Multiple instances are registered for '${getServiceName(serviceId)}'. Unable to resolve a single service using a default strategy.`,
    );
    this.name = 'AmbiguousMatchError';
  }
}
