import { existsSync, mkdirSync, writeFileSync, chmodSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';
import { createHash } from 'node:crypto';
import { Implements, Service, ServiceLifetime } from '@gitlab/needle';
import { Logger, withPrefix } from '@gitlab-org/logging';
import { RG_BINARY_NAME } from './constants';
import { RgBinaryProvider } from './rg_binary_provider';

/**
 * Provider that extracts rg binary from Node.js SEA (Single Executable Application) assets.
 * Used by the Language Server SEA builds.
 */
@Service({
  dependencies: [Logger],
  lifetime: ServiceLifetime.Singleton,
})
@Implements(RgBinaryProvider)
export class SeaRgBinaryProvider implements RgBinaryProvider {
  #logger: Logger;

  #extractedPath: string | null = null;

  constructor(logger: Logger) {
    this.#logger = withPrefix(logger, '[SeaRgBinaryProvider]');
  }

  async getPath(): Promise<string | null> {
    if (this.#extractedPath) {
      return this.#extractedPath;
    }

    try {
      this.#extractedPath = await this.#extractBinary();
      return this.#extractedPath;
    } catch (error) {
      this.#logger.error(
        'Failed to extract ripgrep binary from SEA',
        error instanceof Error ? error : new Error(String(error)),
      );
      return null;
    }
  }

  async #extractBinary(): Promise<string | null> {
    const sea = await import('node:sea');
    if (!sea.isSea()) {
      return null;
    }

    const rgAsset = sea.getAsset('rg');
    if (!rgAsset) {
      return null;
    }

    const binaryData = Buffer.from(rgAsset);
    const hash = createHash('sha256').update(binaryData).digest('hex').slice(0, 8);
    const extractDir = join(tmpdir(), 'gitlab-lsp', 'bin', hash);
    const extractedPath = join(extractDir, RG_BINARY_NAME);

    if (existsSync(extractedPath)) {
      this.#logger.info(`rg already extracted at ${extractedPath}`);
      return extractedPath;
    }

    mkdirSync(extractDir, { recursive: true });
    writeFileSync(extractedPath, binaryData);

    if (process.platform !== 'win32') {
      chmodSync(extractedPath, 0o755);
    }

    this.#logger.info(`rg extracted to ${extractedPath}`);
    return extractedPath;
  }
}
