import { relative, join } from 'node:path';
import { Injectable } from '@gitlab/needle';
import { RepositoryDiscoveryService } from '@gitlab-org/repositories';
import { Logger, withPrefix } from '@gitlab-org/logging';
import { PlainTextResponse } from '@gitlab-org/duo-workflow-service';
import { ToolInputDisplay } from '@gitlab-lsp/workflow-api';
import { WorkflowAction } from '../clients/types';
import { WorkflowActionContext, WorkflowActionHandler, WorkflowActionOf } from './index';

export type FindFilesAction = WorkflowActionOf<'findFiles'>;

@Injectable(WorkflowActionHandler, [Logger, RepositoryDiscoveryService])
export class FindFilesActionHandler implements WorkflowActionHandler<FindFilesAction> {
  #logger: Logger;

  #repositoryDiscoveryService: RepositoryDiscoveryService;

  constructor(logger: Logger, repositoryDiscoveryService: RepositoryDiscoveryService) {
    this.#logger = withPrefix(logger, '[FindFilesActionHandler]');
    this.#repositoryDiscoveryService = repositoryDiscoveryService;
  }

  name = 'find_files';

  formatInput(args: Record<string, unknown>): ToolInputDisplay {
    return {
      tool: 'find_files',
      pattern: args.name_pattern as string,
    };
  }

  canHandle(action: WorkflowAction): action is FindFilesAction {
    return Boolean(action.findFiles);
  }

  async execute(
    { findFiles }: FindFilesAction,
    { workspaceFolderPath }: WorkflowActionContext,
  ): Promise<PlainTextResponse> {
    const { name_pattern: namePattern } = findFiles;

    this.#logger.debug(`Finding files in repo with pattern "${namePattern}"`);

    const repos =
      await this.#repositoryDiscoveryService.getRepositoriesForWorkspace(workspaceFolderPath);

    const allFiles = await Promise.all(
      repos.map(async (repo) => {
        const files = await repo.getFiles(namePattern);
        // Get the repository's path relative to the workspace
        const repoRelativePath = relative(workspaceFolderPath, repo.fsPath);
        // Combine repository path with each file path to get workspace-relative paths
        return files.map((filePath) => join(repoRelativePath, filePath));
      }),
    );

    const response = allFiles.flat().join('\n');

    return {
      response,
      error: '',
    };
  }
}
