import { isCollectionId } from '../../types';
import { ServiceValidator, ValidationContext, ValidationResult } from '../types';
import { UnresolvedDependencyError } from '../../errors';

/**
 * Validates that all non-collection dependencies required by services are registered in the container.
 *
 * This validator ensures that when a service depends on another service (via interface ID),
 * that dependency is actually available in the container. It ignores collection dependencies
 * since collections can be empty by design.
 *
 * A dependency is considered "missing" when no service descriptor in the container
 * has registered itself with the required interface ID.
 */
export class DependencyExistenceValidator implements ServiceValidator {
  readonly name = 'DependencyExistenceValidator';

  validate({ validationData }: ValidationContext): ValidationResult {
    const { nodes, lookup } = validationData;
    const errors: Error[] = nodes.flatMap((node) =>
      node.dependencyIds
        .filter((depId) => !isCollectionId(depId))
        .filter((depId) => !lookup.has(depId))
        .map((depId) => new UnresolvedDependencyError(node.identifiers[0], depId)),
    );

    return {
      isValid: errors.length === 0,
      errors,
    };
  }
}
