import { ServiceDescriptor, ServiceLifetime, AsyncDisposable, hasLifetime } from '../../types';
import { disposeValue } from '../../types/disposable';
import { ServiceResolutionContext, ServiceResolutionMiddleware } from '../types';

export class SingletonResolutionMiddleware implements ServiceResolutionMiddleware, AsyncDisposable {
  #instances = new Map<ServiceDescriptor, unknown>();

  handle<T>(context: ServiceResolutionContext, next: () => T | null) {
    if (!hasLifetime(context.serviceDescriptor, ServiceLifetime.Singleton)) {
      return next();
    }

    if (this.#instances.has(context.serviceDescriptor)) {
      return this.#instances.get(context.serviceDescriptor) as T;
    }

    const service = next();
    if (service) this.#instances.set(context.serviceDescriptor, service);
    return service;
  }

  async disposeAsync(): Promise<void> {
    const results = await Promise.allSettled(
      [...this.#instances.values()].map((instance) => disposeValue(instance)),
    );

    this.#instances.clear();

    const failures = results.filter((r): r is PromiseRejectedResult => r.status === 'rejected');

    if (failures.length > 0) {
      throw new AggregateError(
        failures.map((f) => f.reason),
        `${failures.length} service(s) failed to dispose`,
      );
    }
  }
}
