import { ServiceIdentifier } from '../types';
import { getServiceName } from './utils';

/**
 * Error thrown when a service dependency cannot be resolved.
 */
export class UnresolvedDependencyError extends Error {
  constructor(serviceId: ServiceIdentifier, dependencyId: ServiceIdentifier) {
    super(
      `Service '${getServiceName(serviceId)}' depends on '${getServiceName(dependencyId)}' which couldn't be resolved.`,
    );
    this.name = 'UnresolvedDependencyError';
  }
}
