// src/service_provider.ts
import { ServiceIdentifier, ServiceLocator } from './types';
import { ServiceResolver } from './resolver';
import { ContextualServiceLocator } from './contextual_service_locator';

/**
 * Provides access to registered services in the dependency injection container.
 */
export class ServiceProvider implements ServiceLocator {
  #locator: ContextualServiceLocator;

  #scopeId: symbol;

  #serviceResolver: ServiceResolver;

  #onDispose: (() => void | Promise<void>) | undefined;

  #disposed: boolean = false;

  constructor(serviceResolver: ServiceResolver, onDispose?: () => void | Promise<void>) {
    this.#scopeId = Symbol('Scope');
    this.#serviceResolver = serviceResolver;
    this.#locator = new ContextualServiceLocator(serviceResolver, this.#scopeId);
    this.#onDispose = onDispose;
  }

  /**
   * Retrieves all registered services for the specified identifier.
   * @param identifier - The service identifier
   * @returns Array of service instances
   */
  getServices<T>(identifier: ServiceIdentifier<T>): T[] {
    this.#throwIfDisposed();
    return this.#locator.getServices(identifier);
  }

  /**
   * Retrieves a single registered service for the specified identifier.
   * If more than one service is registered, an error is thrown.
   * If no service is registered, an error is thrown.
   *
   * @param identifier - The service identifier
   * @returns The service instance
   */
  getRequiredService<T>(identifier: ServiceIdentifier<T>): T {
    this.#throwIfDisposed();
    return this.#locator.getRequiredService(identifier);
  }

  /**
   * Creates a new child scope for dependency resolution.
   *
   * Scoped services are instantiated once per scope, allowing for isolated
   * dependency trees. Each scope must be explicitly disposed when no longer needed to prevent memory leaks.
   *
   * @returns A new ServiceProvider with its own scope for resolving services
   */
  createScope(): ServiceProvider {
    this.#throwIfDisposed();
    return new ServiceProvider(this.#serviceResolver);
  }

  /**
   * Disposes the current scope and releases all scoped resources.
   *
   * This method awaits async disposal of services that implement AsyncDisposable,
   * and synchronously disposes services that only implement Disposable.
   *
   * Note: This does not affect singleton services which persist for the lifetime
   * of the application, nor does it affect services resolved in parent or sibling scopes.
   */
  async dispose(): Promise<void> {
    if (this.#disposed) {
      return;
    }

    await this.#serviceResolver.disposeScope(this.#scopeId);
    await this.#onDispose?.();
    this.#disposed = true;
  }

  async [Symbol.asyncDispose](): Promise<void> {
    await this.dispose();
  }

  #throwIfDisposed(): void {
    if (this.#disposed) {
      throw new Error('Cannot perform operation on disposed ServiceProvider');
    }
  }
}
