// "raw" interfaces are exactly what we get from the gitleaks project.
// We later parse these and convert all regexes from strings to RegExp for faster runtime evaluation
export interface IRawGitleaksConfig {
  title: string;
  allowlist: IRawGitleaksGlobalAllowlist;
  rules: IRawGitleaksRule[];
}

export interface IRawGitleaksGlobalAllowlist {
  description: string;
  paths: string[];
  regexes: string[];
  stopwords: string[];
}

export interface IRawGitleaksRuleAllowlist {
  regexes?: string[];
  description?: string;
  regexTarget?: 'match' | 'line' | 'secret'; // Default: 'secret'
  stopwords?: string[];
  condition?: 'and' | 'or' | 'AND' | 'OR' | '&&' | '||'; // Default: 'or', support gitleaks formats
  paths?: string[];
}

export interface IRawGitleaksRule {
  id: string;
  description: string;
  regex?: string;
  keywords?: string[];
  path?: string;
  entropy?: number;
  allowlists?: IRawGitleaksRuleAllowlist[];
  secretGroup?: number;
}

// Parsed interfaces - precompiled regexes for runtime use
export interface IParsedGitleaksConfig {
  title: string;
  allowlist: IParsedGitleaksGlobalAllowlist;
  rules: IParsedGitleaksRule[];
}

export interface IParsedGitleaksGlobalAllowlist {
  description: string;
  paths: RegExp[];
  regexes: RegExp[];
  stopwords: string[];
}

export interface IParsedGitleaksRuleAllowlist {
  regexes?: RegExp[];
  description?: string;
  regexTarget?: 'match' | 'line' | 'secret'; // Default: 'secret'
  stopwords?: string[];
  condition?: 'and' | 'or'; // Normalized to lowercase
  paths?: RegExp[];
}

export interface IParsedGitleaksRule {
  id: string;
  description: string;
  regex?: RegExp;
  keywords?: string[];
  path?: RegExp;
  entropy?: number;
  allowlists?: IParsedGitleaksRuleAllowlist[];
  secretGroup?: number;
}

