import { isCollectionId } from '../../types';
import { ServiceValidator, ValidationContext, ValidationResult } from '../types';
import { MultipleDependencyImplementationsError } from '../../errors';

/**
 * Validates that non-collection dependencies have exactly one implementation registered.
 *
 * When a service depends on an interface, this validator ensures that there is only
 * one service registered for that interface. Having multiple implementations for a
 * non-collection dependency would cause ambiguity during resolution.
 *
 * Collection dependencies (created with createCollectionId) are specifically excluded
 * from this validation as they are designed to support multiple implementations.
 */
export class SingleImplementationValidator implements ServiceValidator {
  readonly name = 'SingleImplementationValidator';

  validate({ validationData }: ValidationContext): ValidationResult {
    const { nodes, lookup } = validationData;
    const errors = nodes.flatMap((node) =>
      node.dependencyIds
        .filter((depId) => !isCollectionId(depId))
        .filter((depId) => {
          const impls = lookup.get(depId);
          return impls && impls.length > 1;
        })
        .map((depId) => new MultipleDependencyImplementationsError(node.identifiers[0], depId)),
    );

    return {
      isValid: errors.length === 0,
      errors,
    };
  }
}
