import { createInterfaceId } from '@gitlab/needle';
import { McpServerSandboxOverrides } from './sandbox_config_types';

export interface StdioLaunchParams {
  command: string;
  args: string[];
  env?: Record<string, string>;
}

export interface McpStdioSandboxWrapper {
  /**
   * Wrap a STDIO MCP server launch with sandboxing if enabled and available.
   * Returns modified params with provider prefix, or the original params if wrapping is skipped.
   */
  wrapIfEnabled(
    serverName: string,
    params: StdioLaunchParams,
    workspacePath: string,
    overrides?: McpServerSandboxOverrides,
  ): Promise<StdioLaunchParams>;
}

export const McpStdioSandboxWrapper =
  createInterfaceId<McpStdioSandboxWrapper>('McpStdioSandboxWrapper');
